	subtitle = "Mestra de Caça da Encruzilhada",
	found = "A Encruzilhada",
	hint = "Fale com a orc que põe os jovens no caminho do caçador.",
	allegiance = "Horda",
	aliases = { "Sergra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Sergra Darkthorn põe os jovens da {link:horde}Horda{/link} no caminho do caçador nos {link:the-barrens}Sertões{/link}. Ela os envia primeiro contra moas das planícies e zhevras, depois contra espreitadores e raptores e, por fim, contra Echeyakee, o leão branco. Ela não tolera insolência. O Chefe Guerreiro declarou as mulheres da Horda iguais aos seus homens, e ela faz questão de ser tratada assim. Alguns de seus próprios camaradas a acham dura, mas ela pede a seus caçadores que reflitam sobre as vidas que tiram.]=],
