Translate("ptBR", "apothecary-helbrim", {
	title = "Boticário Helbrim",
	subtitle = "Boticário da Encruzilhada",
	found = "A Encruzilhada",
	hint = "Fale com o boticário Renegado que trabalha na Encruzilhada.",
	allegiance = "Real Sociedade de Boticários · Renegados",
	aliases = { "Helbrim" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Boticário Helbrim é um dos {link:forsaken}Renegados{/link} da {link:royal-apothecary-society}Real Sociedade de Boticários{/link}, enviado para longe de {link:lordaeron}Lordaeron{/link} para trabalhar na {link:the-crossroads}Encruzilhada{/link}. Ele estuda o que as toxinas de sua terra natal fazem com as feras de {link:kalimdor}Kalimdor{/link}. Também é atraído pelos oásis, cujas águas transformam toda planta e criatura que as bebe. Os Renegados honram seus contratos, diz ele, e ele paga quem lhe traz aquilo de que precisa.]=],
		},
		{
			title = "Importância",
