})

Translate("ptBR", "gazlowe", {
	title = "Gazlowe",
	subtitle = "Senhor de Vila Catraca",
	found = "Vila Catraca",
	hint = "Fale com o goblin que comanda o porto de Vila Catraca.",
	allegiance = "Cartel Bondebico · Vila Catraca",
	sections = {
		{
			title = "Resumo",
			text = [=[Gazlowe é o goblin que fundou {link:ratchet}Vila Catraca{/link} e ainda a comanda. É construtor de ofício e mercador por natureza. Quando os orcs chegaram a {link:kalimdor}Kalimdor{/link}, {link:thrall}Thrall{/link} o contratou como engenheiro-chefe da nova nação de {link:durotar}Durotar{/link}, e suas equipes ajudaram a erguer as muralhas de {link:orgrimmar}Orgrimmar{/link}. Thrall pagou-lhe bem. Com esse ouro, Gazlowe construiu um porto seu na foz do Rio Furiaustral, onde qualquer um pode negociar, desde que pague.]=],
		},
		{
			title = "Importância",
			text = [=[Gazlowe é o mais antigo amigo goblin da {link:horde}Horda{/link}. Seu porto é terreno neutro, aberto também à {link:alliance}Aliança{/link}, mas sua boa vontade para com os orcs é bem conhecida. Por {link:ratchet}Vila Catraca{/link} passa boa parte do que a Horda compra de além-mar.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele serviu como engenheiro-chefe de {link:durotar}Durotar{/link} nos anos de sua fundação.
• Ele fundou {link:ratchet}Vila Catraca{/link} como porto do {link:steamwheedle-cartel}Cartel Bondebico{/link}.
• Ele enviou seu homem, {link:rezlak}Rezlak{/link}, para continuar ajudando os orcs em Durotar.
• Ele patrocina os corredores goblins de {link:thousand-needles}Mil Agulhas{/link} e caça peças para suas máquinas.
• Ele construiu um observatório em Vila Catraca e aguarda suas lentes.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco se escreveu aqui sobre a vida de Gazlowe antes de {link:durotar}Durotar{/link}. Este registro guarda apenas o que seus feitos e seu porto revelam.]=],
		},
	},
	chapters = {
		{
			title = "Os Flibusteiros",
			hint = "Expulse os piratas da costa ao sul de Vila Catraca.",
			text = [=[Os príncipes mercantes despejam ouro em suas frotas, e ainda assim os piratas dos Flibusteiros dos Mares do Sul atacam seus navios. Gazlowe resmunga que o almirante das frotas faz pouco demais. Quando os piratas levaram suas mercadorias, entre elas uma lente para seu observatório e um caixote de botas da {link:booty-bay}Angra do Butim{/link}, ele contratou outros para recuperá-las.]=],
		},
		{
			title = "O Capitão do Heedless",
			hint = "Reivindique a recompensa pelo barão pirata.",
			text = [=[Gazlowe ofereceu uma recompensa pelo {link:baron-longshore}Barão Longshore{/link}, o gilneano que lidera os Flibusteiros, e pediu seus restos num estado que ele pudesse reconhecer. Quando a tarefa foi cumprida, admitiu que certa vez vira o navio do barão deslizar pelo mar aberto e achara aquilo uma bela visão.]=],
		},
		{
			title = "O Tubarão",
			hint = "Atenda ao chamado por pescadores afixado em Vila Catraca.",
			text = [=[Um grande tubarão começou a rondar as águas junto à doca, atacando marinheiros e pequenos barcos. Os estivadores o chamavam de Bruuz, e logo nenhuma tripulação queria entrar na água. Gazlowe ofereceu uma recompensa por sua barbatana. Quando a barbatana chegou, disse que talvez a pusesse na sopa, para rir por último.]=],
		},
	},
	mentions = {
		{ text = "O Carregamento Perdido" },
		{ text = "O Carregamento Perdido, a resposta de Dizzywig" },
		{ text = "Patrocínio Goblin" },
		{ text = "Patrocínio Goblin, o regulador de combustível perdido" },
		{ text = "Problemas nas Docas, um presente de vinho do Porto antigo" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "contratou-o para construir Durotar" },
		{ id = "rezlak", name = "Rezlak", note = "seu homem em Durotar" },
		{ id = "baron-longshore", name = "Barão Longshore", note = "o pirata que ele queria morto" },
		{ id = "innkeeper-wiley", name = "Estalajadeiro Wiley", note = "cuida da estalagem de seu porto" },
	},
})

Translate("ptBR", "innkeeper-wiley", {
	title = "Estalajadeiro Wiley",
	subtitle = "Estalajadeiro de Vila Catraca",
	found = "A estalagem de Vila Catraca",
	hint = "Fale com o estalajadeiro de Vila Catraca.",
