	sections = {
		{
			title = "Resumo",
			text = [=[O Estalajadeiro Wiley cuida da estalagem de {link:ratchet}Vila Catraca{/link}, onde marinheiros, comerciantes e soldados das duas facções se sentam sob o mesmo teto. Ele serve bebida a orcs e humanos por igual e faz poucas perguntas. Em Vila Catraca diz-se que ele registra os feitos de quem se hospeda sob seu teto, e que honrarias chegam àqueles cujos nomes ele anota.]=],
