	},
	bonds = {
		{ id = "gazlowe", name = "Gazlowe", note = "senhor do porto" },
	},
})

Translate("ptBR", "mankrik", {
	title = "Mankrik",
	subtitle = "O Guerreiro Enlutado",
	found = "A Encruzilhada",
	hint = "Fale com o orc que observa o horizonte da Encruzilhada.",
	allegiance = "Horda",
	sections = {
		{
			title = "Resumo",
			text = [=[Mankrik é um guerreiro {link:orcs}orc{/link} da {link:the-crossroads}Encruzilhada{/link}. Ele e sua esposa lutavam ao lado dos taurens num pequeno acampamento quando os javatuscos os sobrepujaram. Ela conteve três deles sozinha. Ele levou outros para longe e, quando se voltou, viu-a cair. Então o derrubaram. Um druida {link:tauren}tauren{/link} o encontrou na {link:gold-road}Estrada do Ouro{/link} e cuidou de seus ferimentos. Agora ele fica na Encruzilhada do amanhecer ao anoitecer, olhando o horizonte, e já matou todo {link:quilboar}javatusco{/link} que encontrou desde então.]=],
		},
		{
			title = "Importância",
			text = [=[O luto de Mankrik é conhecido por todos que passam pela {link:the-crossroads}Encruzilhada{/link}. Para muitos, ele é a prova do quanto custa a guerra contra os javatuscos.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele jurou vingança contra os javatuscos que lhe tiraram a esposa.
• Ele pede as presas dos {link:bristleback-quilboar}Costagulha{/link}, para celebrar suas mortes.
• Ele está construindo um memorial para ela.]=],
		},
	},
	chapters = {
		{
			title = "Perdida em Batalha",
			hint = "Procure a esposa de Mankrik.",
			text = [=[Mankrik pediu apenas algum sinal dela. Ela foi encontrada onde a luta havia acontecido, e estava morta. Ele recebeu a notícia em silêncio. Depois voltou à sua vigília.]=],
		},
		{
			title = "O Nome Dela É Olgra",
			hint = "Recupere os adornos da esposa de Mankrik.",
			text = [=[O curandeiro que salvou Mankrik não pôde salvá-la. O nome dela era {link:olgra}Olgra{/link}. Ela usava muitas joias de osso polido, obras de arte feitas por ela mesma, e elas haviam sumido de seu corpo. Mankrik pediu que fossem tomadas de volta dos {link:razormane-quilboar}Crinavalha{/link} que as levaram, para que pudesse colocá-las em seu memorial e nunca esquecê-la.]=],
		},
	},
	mentions = {
		{ text = "Consumido pelo Ódio" },
	},
	bonds = {
		{ id = "olgra", name = "Olgra", note = "sua esposa" },
