})

Translate("ptBR", "kolkar-centaurs", {
	title = "Centauros Kolkar",
	aliases = { "Kolkar", "centauros Kolkar", "tribo Kolkar" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Kolkar são uma tribo de {link:centaurs}centauros{/link} que percorre os {link:the-barrens}Sertões{/link} e as terras ao redor. Seus cavaleiros acampam junto aos oásis, caçam as feras que vêm beber e caem sobre os viajantes nas estradas. Atacaram os taurens durante anos antes da chegada dos orcs, e atacam a {link:horde}Horda{/link} desde então.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Por muito tempo, os Kolkar dos {link:the-barrens}Sertões{/link} foram dispersos e desordenados. Agora novos líderes surgiram entre eles: {link:barak-kodobane}Barak Kodobane{/link}, perto dos {link:the-forgotten-pools}Charcos Esquecidos{/link}; {link:verog-the-dervish}Verog, o Dervixe{/link}, no {link:the-stagnant-oasis}Oásis Estagnado{/link}; e {link:hezrul-bloodmark}Hezrul Bloodmark{/link}, o maior deles, no {link:lushwater-oasis}Oásis das Águas Claras{/link}. Sob esses chefes, a tribo tornou-se uma verdadeira ameaça. {link:regthar-deathgate}Regthar Deathgate{/link} os caça de suas casamatas a oeste da {link:the-crossroads}Encruzilhada{/link} e, quando seus líderes caíram, um bando de guerra veio da terra natal dos Kolkar, em {link:desolace}Desolação{/link}, em busca de vingança. Em {link:durotar}Durotar{/link}, outro bando domina a garganta rochosa do {link:kolkar-crag}Penedo de Kolkar{/link}.]=],
		},
	},
})

Translate("ptBR", "razormane-quilboar", {
	title = "Javatuscos Crinavalha",
	aliases = { "Crinavalha", "tribo Crinavalha", "javatuscos Crinavalha" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Crinavalha são uma tribo de {link:quilboar}javatuscos{/link} do norte e do sul dos {link:the-barrens}Sertões{/link}. Eles erguem seus acampamentos entre grandes vinhas espinhosas que brotam da terra e reverenciam o espírito javali Agamaggan, de cujo sangue, diz-se, nasceram os espinhos. Antes da chegada dos orcs, percorriam a terra que hoje é {link:durotar}Durotar{/link}, e nunca aceitaram sua perda.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Os Crinavalha estão em guerra com a {link:horde}Horda{/link} e com seus primos da tribo {link:bristleback-quilboar}Costagulha{/link}. Dominam o {link:thorn-hill}Morro dos Espinhos{/link}, a leste da {link:the-crossroads}Encruzilhada{/link}, a {link:bramblescar}Espinheira{/link}, nas planícies centrais, e a {link:blackthorn-ridge}Serra de Abrunhal{/link}, no sul. Seus ataques às caravanas de {link:durotar}Durotar{/link} foram liderados por três membros da tribo saídos do {link:razorfen-kraul}Urzal dos Tuscos{/link}: {link:nak}Nak{/link}, Kuz e {link:lok-orcbane}Lok Orcbane{/link}. O ferreiro do {link:camp-taurajo}Acampamento Taurajo{/link} descobriu que suas armas estão ficando mais resistentes. Numa caverna do Morro dos Espinhos, os Crinavalha falam de uma fera monstruosa de seu próprio sangue, o Devorador.]=],
		},
	},
})
